"""Since we're interested in the Visible spectrum of the emission plasma, we take the Balmer Series emission band only and consider wavelenghts between 195 nm to 1100 nm.

Df_scaled is our scaled data. we iterate through and remove the last 50 columns and reshape into 50 rows and 90 columns
"""

# Creating a for loop to convert the entire dataframe into a 2D matrix

pixels_img = []

for index, row in Df_scaled.iterrows(): # so we exclude the 50 columns
  rwl_50 = row.iloc[:-50]

  pixels = rwl_50.values.reshape(50, 90) # first to an array and then 2D matrix

  pixels_img.append(pixels)

pixels_img[500].shape # checking the shape

