df_scaled.loc[(df_scaled['H_ppm'] == 0) & (df_scaled['Meth_ppm'] > 0), 'Category'] = 'Methane Only'
df_scaled.loc[(df_scaled['H_ppm'] > 0) & (df_scaled['Meth_ppm'] > 0), 'Category'] = 'Hydrogen and Methane'
